  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema before running (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = tool.compiledValidator;
    if (validator && !validator(input)) {
      return buildSchemaRejection(name, validator.errors ?? []);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function compileInputSchema(ajv: Ajv, toolName: string, schema: Record<string, unknown>): ValidateFunction {
  if (!isSyncSchemaObject(schema)) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": async schemas are not supported`);
  }
  try {
    return ajv.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${reason}`);
  }
}

function isSyncSchemaObject(schema: Record<string, unknown>): schema is SchemaObject {
  return schema.$async !== true;
}

interface SchemaFailureDetail {
  path: string;
  constraint: string;
  summary: string;
}

function buildSchemaRejection(toolName: string, validationErrors: ErrorObject[]): ToolResponse {
  const failures = validationErrors.map(describeValidationError);
  log.warn('tool', 'input validation failed', {
    name: toolName,
    failures: failures.map(({path, constraint}) => ({path, constraint})),
  });
  const reasons = failures.map(failure => failure.summary).join('; ');
  return {result: `Invalid input for tool "${toolName}": ${reasons}`};
}

function describeValidationError(validationError: ErrorObject): SchemaFailureDetail {
  const rawPath = validationError.instancePath.slice(1);
  const basePath = rawPath.replaceAll('/', '.');
  if (validationError.keyword === 'required') {
    const missingProperty = String(validationError.params.missingProperty);
    const path = [basePath, missingProperty].filter(Boolean).join('.');
    return {path, constraint: 'required', summary: `${path} is required`};
  }
  const path = basePath || '<root>';
  if (validationError.keyword === 'type') {
    const expectedType = String(validationError.params.type);
    return {path, constraint: `type: ${expectedType}`, summary: `${path} must be of type ${expectedType}`};
  }
  return {
    path,
    constraint: validationError.keyword,
    summary: `${path} failed ${validationError.keyword} constraint`,
  };
}
